import{_ as t,o as i,c as n,a2 as o}from"./chunks/framework.DPTp4bo7.js";const u=JSON.parse('{"title":"Investigating the Mysterious Constant 11.8/h (Abandoned)","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/investigating-the-mysterious-constant-11-8-h"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/investigating-the-mysterious-constant-11-8-h"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/investigating-the-mysterious-constant-11-8-h"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/investigating-the-mysterious-constant-11-8-h"}]]},"headers":[],"relativePath":"investigating-the-mysterious-constant-11-8-h.md","filePath":"logistics/src/page-Aoh27KC22zbHpXeBVPKXpY.md"}'),a={name:"investigating-the-mysterious-constant-11-8-h.md"};function s(r,e,l,d,h,p){return i(),n("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="关于神秘常数11-8-h的相关探究-已被抛弃" aria-hidden="true"></span><h1 id="investigating-the-mysterious-constant-11-8-h-abandoned" tabindex="-1">Investigating the Mysterious Constant 11.8/h (Abandoned) <a class="header-anchor" href="#investigating-the-mysterious-constant-11-8-h-abandoned" aria-label="Permalink to &quot;Investigating the Mysterious Constant 11\\.8/h (Abandoned)&quot;">​</a></h1><blockquote><p>Source page ID: <code>Aoh27KC22zbHpXeBVPKXpY</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Aoh27KC22zbHpXeBVPKXpY" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><details><summary>Problem overview:</summary><ol><li><p>In crucible liquid-disappearance research, a fully supplied crucible ran for 5 hours, 5*1800=9000 reactions, losing liquid 59 times: about 11.8/hour. Two tests agreed. A one-hour test of 1800 reactions lost liquid 11 times, giving approximately 11.8 losses/h.</p></li><li><p>Below, every output stall adds 1 item to the overflow stash. Tests found approximately 1 item per 5 minutes, or 12/h. Over longer periods the rate fell, perhaps toward 11.8/h. <img src="/endfield-skydoc/logistics/src/assets/images/img-155e0bd6c2f34e94.q90-5d34a0d6c786d943.webp" alt="Investigating the Mysterious Constant 118/h (Abandoned)"></p></li><li><p>At Tianjingyuan (天井院; provisional), a water loop simultaneously <s>pumping and dumping</s> operating a Fluid Pump and Fluid Supply Unit lost 11~11.92 drops/h, approximately 11.8/h.</p></li></ol><p>These coinci(inevi)dences caught our attention. Future slowdown phenomena could be measured for a connection to this constant. It may represent 11.8 delays per 1800 outputs rather than h^-1.</p></details><p>On 2026/3/21, crucible liquid disappearance was fixed, but the other two remained. Their connection may be weak, and this investigation may not hold.</p><p>Early on 2026/3/30, belt slowdown was fixed. This proposition will soon be abandoned.</p></div>',1)])])}const g=t(a,[["render",s]]);export{u as __pageData,g as default};
